examples.code:
mock_provider "aws" {}

variables {
  entorno     = "dev"
  bucket_name = "nicocano-test-assets"
}

run "nombre_correcto" {
  command = plan
  assert {
    condition     = aws_s3_bucket.assets.bucket == "nicocano-test-assets"
    error_message = "El nombre del bucket no coincide."
  }
}

run "rechaza_entorno_invalido" {
  command = plan
  variables { entorno = "qa" }
  expect_failures = [var.entorno]
}

plugin "terraform" {
  enabled = true
  preset  = "recommended"
}
plugin "aws" {
  enabled = true
  version = "0.40.0"
  source  = "github.com/terraform-linters/tflint-ruleset-aws"
}

resource "aws_s3_bucket" "publico" {
  # checkov:skip=CKV_AWS_20: bucket de sitio estático público por diseño
  bucket = "nicocano-sitio"
}

terraform {
  encryption {
    key_provider "pbkdf2" "clave" {
      passphrase = var.state_passphrase
    }
    method "aes_gcm" "metodo" {
      keys = key_provider.pbkdf2.clave
    }
    state {
      method = method.aes_gcm.metodo
    }
  }
}
